CHANGELOG = '## [0.256.0] - six fixes from the first windowed run of the authoring loop\n\n**The walker ran the loop in the Godot editor, 2026-10-26** (the factory\'s roadmap 318). Each fix is a defect they hit.\n\n### Fixed\n1. **The progress bar went backwards.** It counted finished jobs over the jobs the index had met so far, and the\n   index meets jobs as the run reaches them.\n   - `run` now records its plan before it dispatches anything: `.level_factory/runs/<mission>.json`, every planned\n     job and the start time.\n   - `layouts.index_progress` counts the jobs finished since that start against that fixed total, and says nothing\n     until this run\'s plan exists.\n2. **Whole numbers read as decimals** ("revision 1.0", "Seed 9003.0"), because Godot reads every JSON number as a\n   float. `LevelPanel.whole()` prints them as written.\n3. **The Setup tab cut every column off in a narrow dock.** Each check\'s cells carry their whole text as tooltips,\n   and the readiness column is wide enough for "warning".\n4. **The bar sat at 99% through the walk\'s last stage and read as stuck.** Every walk stage says "Stage n of m",\n   and a stage that cannot count puts the bar in motion (indeterminate) instead of leaving the last number on it.\n5. **A panel that restarted mid-walk lost the walk.** The walk went on, its result landed where nobody watched, and\n   Stop reached another run.\n   - The service client records the operation it starts (`user://factory_runs/current_<owner>.json`).\n   - The Level tab re-attaches to it on load, after its quick loads: a run still going is followed to its result,\n     and one that finished meanwhile is shown once. Stop still reaches it through its cancel file.\n   - A resumed run is followed by its result file alone, because Godot can only ask about processes it started\n     itself.\n6. **Nothing opened a walk already built.** "Open the last walk" launches the preview the last walk record names,\n   on a reopened level too, without building it again.\n\n### Tests\n- `tests/integration/test_run_progress.py`, through the real CLI on the stub tools (fails on 0.255.0):\n  - `run` records exactly the planned jobs;\n  - progress reads N of N at the end;\n  - a stale plan says nothing;\n  - jobs finished before the run started do not count.\n- `apps/godot/tests/test_panel_numbers.gd`: whole numbers, the moving bar, the Setup tab\'s tooltips.\n- `apps/godot/tests/test_panel_resume.gd`: a walk that finished while nobody watched is shown at once; a running one\n  is followed, Stop reaches it, and its answer lands; "Open the last walk" appears with a walk record, and only then.\n\n'
OLD_VERSION, NEW_VERSION = '0.255.0', '0.256.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
